const MOA = (x: number, y: number, s = 1) => longHair(x, y, s, "#2b1d14") + kid(x, y, "#e07b00", "#2b1d14", s);
const YAS = (x: number, y: number, s = 1) => kid(x, y, "#f2a541", "#2b1d14", s);
const BENGT = (x: number, y: number, s = 1) => kid(x, y, "#8a6a44", "#d8d8d8", s) + beard(x, y, s, "#e2e2e2");
const KARIN = (x: number, y: number, s = 1) => kid(x, y, "#1f3a5f", "#9a9aa0", s) + `<path d="M${x - 6 * s} ${y + 22 * s} L${x} ${y + 40 * s} L${x + 6 * s} ${y + 22 * s}Z" fill="#fff"/>`;
const bubble = (x: number, y: number, w: number, txt: string, size = 22) => `<rect x="${x - w / 2}" y="${y - 22}" width="${w}" height="36" rx="14" fill="#fff" stroke="#1d2433" stroke-width="2"/><text x="${x}" y="${y + 3}" font-family="Caveat,cursive" font-weight="700" font-size="${size}" text-anchor="middle" fill="#1d2433">${txt}</text>`;
const room = (bg = "#f5efe2") => `<rect width="300" height="300" fill="${bg}"/><rect y="230" width="300" height="70" fill="#c8a879"/>`;
const board = (txt = "", size = 30) => `<rect x="40" y="34" width="220" height="96" rx="4" fill="#2f5a46" stroke="#8a6a44" stroke-width="5"/><text x="150" y="92" font-family="Caveat,cursive" font-weight="700" font-size="${size}" text-anchor="middle" fill="#f3efe6">${txt}</text>`;
const ICON = (body: string, bg: string) => `<svg viewBox="0 0 320 180"><rect width="320" height="180" fill="${bg}"/>${body}</svg>`;
const txt = (x: number, y: number, s: string, size = 20, c = "#1d2433", w = 700) => `<text x="${x}" y="${y}" font-family="Caveat,cursive" font-weight="${w}" font-size="${size}" text-anchor="middle" fill="${c}">${s}</text>`;
const town = `<rect width="300" height="300" fill="#dbe4ee"/><rect x="0" y="96" width="70" height="140" fill="#c9b8a6"/><path d="M0 96 L35 64 L70 96Z" fill="#9a6b4f"/><rect x="74" y="70" width="80" height="166" fill="#d9cdb8"/><rect x="158" y="104" width="62" height="132" fill="#b9c4cf"/><path d="M158 104 L189 78 L220 104Z" fill="#7a8a99"/><rect x="224" y="84" width="76" height="152" fill="#cfb9a0"/>${[[12, 116], [44, 116], [88, 90], [122, 90], [88, 130], [122, 130], [172, 124], [198, 124], [238, 104], [272, 104], [238, 144], [272, 144]].map(([x, y]) => `<rect x="${x}" y="${y}" width="16" height="22" fill="#eef4fb" stroke="#8a7a6a"/>`).join("")}<rect y="230" width="300" height="70" fill="#b8b3aa"/>`;
const sign = (x: number, y: number, s: string, c = "#2f7d4a", w = 96, rot = 0) => `<g transform="rotate(${rot} ${x} ${y})"><rect x="${x - 3}" y="${y}" width="6" height="66" fill="#8d6440"/><rect x="${x - w / 2}" y="${y - 44}" width="${w}" height="48" rx="4" fill="#fff" stroke="${c}" stroke-width="3"/>${txt(x, y - 14, s, 16, c)}</g>`;
const mega = (x: number, y: number) => `<path d="M${x} ${y - 5} L${x + 28} ${y - 16} L${x + 28} ${y + 16} L${x} ${y + 5}Z" fill="#e0b43a" stroke="#1d2433" stroke-width="2"/><rect x="${x - 8}" y="${y - 5}" width="10" height="10" fill="#1d2433"/>`;
const pad = (x: number, y: number) => `<rect x="${x}" y="${y}" width="34" height="44" rx="3" fill="#fff" stroke="#9aa8c4" stroke-width="2"/><path d="M${x + 6} ${y + 12} h22 M${x + 6} ${y + 20} h22 M${x + 6} ${y + 28} h16" stroke="#9aa8c4" stroke-width="2"/>`;
const phone = (x: number, y: number) => `<rect x="${x}" y="${y}" width="18" height="30" rx="3" fill="#1d2433"/><rect x="${x + 2}" y="${y + 3}" width="14" height="22" fill="#7fb2e5"/>`;
const news = (x: number, y: number, w: number, h: number, head: string) => `<rect x="${x}" y="${y}" width="${w}" height="${h}" rx="3" fill="#fff" stroke="#9aa8c4" stroke-width="2"/>${txt(x + w / 2, y + 26, head, 18, "#1f4fb0")}${[...Array(Math.max(0, Math.floor((h - 46) / 14)))].map((_, i) => `<path d="M${x + 12} ${y + 44 + i * 14} H${x + w - 12 - (i % 3) * 16}" stroke="#c6d2e4" stroke-width="4"/>`).join("")}`;
const clock = (x: number, y: number, r = 34, hr = 300, mn = 0) => {
  const hand = (deg: number, len: number, w: number) => { const a = (deg - 90) * Math.PI / 180; return `<path d="M${x} ${y} L${(x + Math.cos(a) * len).toFixed(1)} ${(y + Math.sin(a) * len).toFixed(1)}" stroke="#1d2433" stroke-width="${w}" stroke-linecap="round"/>`; };
  return `<circle cx="${x}" cy="${y}" r="${r}" fill="#fff" stroke="#1d2433" stroke-width="4"/>${[...Array(12)].map((_, i) => { const a = i * Math.PI / 6; return `<circle cx="${(x + Math.cos(a) * r * .8).toFixed(1)}" cy="${(y + Math.sin(a) * r * .8).toFixed(1)}" r="${r / 20}" fill="#1d2433"/>`; }).join("")}${hand(hr, r * .5, r / 9)}${hand(mn, r * .75, r / 14)}<circle cx="${x}" cy="${y}" r="${r / 12}" fill="#d63b2f"/>`;
};
const leaf = (x: number, y: number, c: string, rot: number) => `<ellipse cx="${x}" cy="${y}" rx="9" ry="4.5" fill="${c}" transform="rotate(${rot} ${x} ${y})"/>`;
const leaves = (n: number, y0: number, y1: number) => [...Array(n)].map((_, i) => leaf(20 + (i * 67) % 270, y0 + (i * 41) % (y1 - y0), ["#d97b2b", "#e0b43a", "#b8432f"][i % 3], i * 47)).join("");
const sheet = (x: number, y: number, w: number, h: number, rows: number) => `<rect x="${x}" y="${y}" width="${w}" height="${h}" fill="#fffdf7" stroke="#c9c2b4" stroke-width="2" transform="rotate(-3 ${x + w / 2} ${y + h / 2})"/>${[...Array(rows)].map((_, i) => `<path d="M${x + 12} ${y + 18 + i * 14} H${x + 12 + (w - 24) * (i % 4 === 3 ? .3 : [.9, .7, .8][i % 3])}" stroke="#7d8aa5" stroke-width="3" transform="rotate(-3 ${x + w / 2} ${y + h / 2})"/>`).join("")}`;
const star = (cx: number, cy: number, r: number, on: boolean) => `<path d="${[...Array(10)].map((_, i) => { const a = -Math.PI / 2 + i * Math.PI / 5, rr = i % 2 ? r * .45 : r; return `${i ? "L" : "M"}${(cx + Math.cos(a) * rr).toFixed(1)} ${(cy + Math.sin(a) * rr).toFixed(1)}`; }).join(" ")}Z" fill="${on ? "#f2c94c" : "#e6e2d8"}" stroke="#b8860b" stroke-width="1.5"/>`;
const stars = (x: number, y: number, n: number, r = 12) => [0, 1, 2, 3, 4].map(i => star(x + (i - 2) * r * 2.3, y, r, i < n)).join("");
const bus = (x: number, y: number, s = 1, lit = false) => `<g transform="translate(${x} ${y}) scale(${s})"><rect x="-70" y="-40" width="140" height="70" rx="10" fill="#2a7d9c"/>${[0, 1, 2, 3].map(i => `<rect x="${-62 + i * 30}" y="-30" width="24" height="24" rx="3" fill="${lit ? "#f7e7a1" : "#cfe3f2"}"/>`).join("")}<rect x="56" y="-30" width="10" height="40" fill="${lit ? "#f7e7a1" : "#cfe3f2"}"/><circle cx="-40" cy="32" r="11" fill="#1d2433"/><circle cx="40" cy="32" r="11" fill="#1d2433"/><rect x="-40" y="-52" width="80" height="12" rx="2" fill="#1d2433"/>${txt(0, -42, "NATTBUSSEN", 11, "#f2c94c")}</g>`;
const pine = (x: number, y: number, s = 1, c = "#1f3d2c") => `<path d="M${x} ${y - 50 * s} L${x + 26 * s} ${y + 30 * s} L${x - 26 * s} ${y + 30 * s}Z" fill="${c}"/>`;
const podium = (x: number, y: number, c: string, s: string) => `<path d="M${x - 40} ${y} H${x + 40} L${x + 32} ${y + 66} H${x - 32}Z" fill="${c}"/>${txt(x, y + 40, s, 26, "#fff")}`;
const laptop = (x: number, y: number, s = "AI") => `<rect x="${x - 40}" y="${y - 50}" width="80" height="52" rx="4" fill="#1d2433"/><rect x="${x - 35}" y="${y - 45}" width="70" height="42" fill="#7fb2e5"/>${txt(x, y - 16, s, 24)}<path d="M${x - 50} ${y + 2} H${x + 50} L${x + 44} ${y + 10} H${x - 44}Z" fill="#8a8f99"/>`;
const envelope = (x: number, y: number, s = 1, label = "") => `<g transform="translate(${x} ${y}) scale(${s})"><rect x="-40" y="-26" width="80" height="52" rx="3" fill="#fbfaf5" stroke="#9a8f80" stroke-width="2"/><path d="M-40 -26 L0 4 L40 -26" stroke="#9a8f80" stroke-width="2" fill="none"/>${label ? txt(0, 20, label, 14, "#2257c9") : ""}</g>`;
const locker = (x: number, y: number, c = "#7a9cc6") => `<rect x="${x}" y="${y}" width="44" height="150" fill="${c}" stroke="#56708f" stroke-width="2"/><path d="M${x + 8} ${y + 14} h28 M${x + 8} ${y + 22} h28" stroke="#56708f" stroke-width="2"/><rect x="${x + 34}" y="${y + 70}" width="5" height="14" fill="#33415c"/>`;
const birch = (x: number, y: number, s = 1) => `<rect x="${x - 4 * s}" y="${y}" width="${8 * s}" height="${70 * s}" fill="#f3efe6"/><path d="M${x - 4 * s} ${y + 14 * s} h${5 * s} M${x} ${y + 34 * s} h${4 * s} M${x - 4 * s} ${y + 52 * s} h${6 * s}" stroke="#1d2433" stroke-width="2"/><circle cx="${x}" cy="${y - 6 * s}" r="${22 * s}" fill="#8cc56a"/><circle cx="${x - 16 * s}" cy="${y + 8 * s}" r="${14 * s}" fill="#9fd07a"/><circle cx="${x + 16 * s}" cy="${y + 8 * s}" r="${14 * s}" fill="#9fd07a"/>`;
const lilac = (x: number, y: number) => `<path d="M${x} ${y + 40} V${y + 10}" stroke="#5b8a3c" stroke-width="3"/>${[[0, 0], [-8, 8], [8, 8], [-4, -8], [4, 16], [0, 22], [-6, 24], [6, 2]].map(([dx, dy]) => `<circle cx="${x + dx}" cy="${y + dy}" r="6" fill="#b48ad6"/>`).join("")}`;
const curtains = `<path d="M0 0 H60 Q42 150 60 300 H0Z" fill="#2f5a8a"/><path d="M300 0 H240 Q258 150 240 300 H300Z" fill="#2f5a8a"/><rect width="300" height="18" fill="#1f3f66"/>`;
