/* rhyme families: words in one family rhyme, families do not rhyme with each other */
const RIM: string[][] = [["dag", "slag", "lag", "drag", "svag"], ["år", "går", "får", "hår", "står"], ["vind", "kind", "blind", "lind"], ["hand", "sand", "land", "strand", "band"], ["natt", "katt", "hatt", "skratt", "glatt"], ["fort", "gjort", "kort", "bort"], ["is", "bris", "pris", "ris"], ["sång", "gång", "lång", "tång"], ["ljus", "hus", "brus", "sus"], ["sol", "stol", "kjol", "fiol"]];
/* [line 1, line 2 with ____, the rhyme word] */
const RIMQ: [string, string, string][] = [["Klockan på väggen slår sitt slag,", "sekunder blir till en ____.", "dag"], ["Jag vill hålla den i min hand,", "men den rinner bort som ____.", "sand"], ["En stund är flyktig som en vind,", "den snuddar bara vid min ____.", "kind"], ["Dagarna blir till ett år,", "och ingen vet vart tiden ____.", "går"], ["Min längtan springer alltid fort", "mot allt jag ännu inte ____.", "gjort"], ["Jag tände ett ljus i natt", "och fick syn på en svart ____.", "katt"], ["Vintern kom med snö och is", "och en kall och bitande ____.", "bris"], ["Vi badade hela dagen lång", "och sjöng en gammal ____.", "sång"], ["Jag satt i solen på en stol", "och läste tyst om sommarns ____.", "sol"]];
/* lines to count syllables in: one vowel = one syllable in these lines */
const RAD = ["Klockan på väggen slår sitt slag", "sekunder blir till en dag", "och ingen vet vart tiden går", "En stund är flyktig som en vind", "men den rinner bort som sand", "Min längtan springer alltid fort", "Dagarna blir till ett år", "Ditt liv är nu. Ditt liv är i dag"];
const syl = (s: string) => (s.match(/[aeiouyåäö]/gi) || []).length;
const RIMH = t3("Ord rimmar när de slutar med samma ljud: dag – slag, år – går. Rytmen hör du när du läser högt och räknar stavelserna: varje vokal är en stavelse.", "Words rhyme when they end with the same sound: dag – slag, år – går. You hear the rhythm when you read aloud and count the syllables: each vowel is one syllable.", "تتقافى الكلمات عندما تنتهي بالصوت نفسه: dag – slag، år – går. وتسمع الإيقاع عندما تقرأ بصوت عالٍ وتعدّ المقاطع: كلّ حرف صوتيّ مقطع واحد.");

