const SKALA: string[][] = [["usel", "urusel"], ["dålig", "svag"], ["medioker", "halvbra"], ["okej", "godkänd"], ["bra", "fin"], ["mycket bra", "riktigt bra"], ["lysande", "fantastisk", "briljant"]];
/* [sentence, stronger word, weaker, weaker] or the other way */
const NYANS: [string, string, string, string, boolean][] = [["Filmen är ____ bra.", "riktigt", "ganska", "inte särskilt", true], ["Musiken är ____ spännande.", "otroligt", "lite", "inte särskilt", true], ["Slutet är ____ svagt.", "väldigt", "lite", "ganska", true], ["Filmen är ____ spännande.", "inte särskilt", "väldigt", "otroligt", false], ["Dialogen är ____ bra.", "inte helt", "riktigt", "otroligt", false], ["Skådespelarna är ____ bra.", "ganska", "väldigt", "otroligt", false]];
