const VQ: [string, string][] = [["Filmen var varken bra eller dålig. Den var m…", "medioker"], ["Filmen var helt fantastisk. Den var l…", "lysande"], ["Man visste hela tiden vad som skulle hända. Den var f…", "förutsägbar"], ["Jag satt längst ut på stolen. Den var s…", "spännande"], ["Dialogen var inte bra. Den var s…", "svag"], ["Alla borde se den. Jag r… den.", "rekommenderar"], ["Det är en person i filmen. Det är en k…", "karaktär"]];
const VH = t3("Värdeord visar hur bra något är: usel, svag, medioker, bra, lysande. Små ord som ganska och inte särskilt gör omdömet svagare. Riktigt och otroligt gör det starkare.", "Evaluative words show how good something is: usel, svag, medioker, bra, lysande. Little words like ganska and inte särskilt make the judgement weaker. Riktigt and otroligt make it stronger.", "تبيّن كلمات التقييم مدى جودة الشيء: usel، svag، medioker، bra، lysande. والكلمات الصغيرة مثل ganska وinte särskilt تُضعف الحكم، أمّا riktigt وotroligt فتقوّيه.");

