    if (lv === 1 && Math.random() < .5) {
      const [s, v, r] = pick(VO), right = `Visserligen ${v} ${s} ${r},`, opts = shuffle([right, `Visserligen ${s} ${v} ${r},`, `Visserligen ${s} ${r} ${v},`]);
      return {kind: "choice", opts, ans: opts.indexOf(right), show: right, q: [A.wipe(), head(t3("Vilken ordföljd är rätt?", "Which word order is right?", "أيّ ترتيب للكلمات صحيح؟"), 80, 34), A.tx(`${s} · ${v} · ${r}`, 400, 230, 44), qt(L(t3("Visserligen …, men …", "Admittedly …, but …", "صحيحٌ أنّ …، لكنّ …")), 400, 300, 26, "o")],
        sol: [A.tx(`${right} men …`, 400, 420, 36, "g")], hint};
    }
    const [a, b] = pick(VM), opts = shuffle(["men", "eftersom", "därför"]);
    return {kind: "choice", opts, ans: opts.indexOf("men"), show: "men", q: [A.wipe(), head(t3("Vilket ord passar?", "Which word fits?", "أي كلمة تناسب؟"), 80, 34), ...svLines(`${a} ____ ${b}`, 220, 40)], sol: svLines(`${a} men ${b}`, 400, 32, "g"), hint};
