const PQH = t3("Pluskvamperfekt är hade + supinum: hade skrivit, hade berättat. Det visar vad som hände ännu tidigare, före det som berättelsen handlar om.", "The past perfect is hade + supine: hade skrivit (had written), hade berättat (had told). It shows what happened even earlier, before what the story is about.", "الماضي التامّ هو hade مع supinum: hade skrivit (كانت قد كتبت)، hade berättat (كانت قد حكت). يبيّن ما حدث قبلُ، قبل ما تدور حوله القصّة.");

defineUnit({id: "sv9k", year: 9, ord: 11, title: t3("Novellen: Brevet som aldrig skickades", "Short story: The letter that was never sent", "قصّة قصيرة: الرسالة التي لم تُرسَل أبدًا"), storyTitle: "Brevet som aldrig skickades",
  icon: ICON(`${envelope(120, 92, 1.4, "Till Elsa")}<path d="M220 60 Q250 40 270 70 T300 90" stroke="#b48ad6" stroke-width="4" fill="none" stroke-dasharray="6 6"/>${clock(256, 120, 28, 240, 300)}`, "#f3e9f2"),
  words: ["tillbakablick", "hemlighet", "skuld", "försoning", "kuvert9", "darra", "bekanna", "lättnad"], terms: ["svpluskvamperfekt"],
  story: [
    {text: ["Det var sista veckan i maj. Sara skulle rensa sitt skrivbord innan hon började på gymnasiet. Längst in i den nedersta lådan låg ett vitt kuvert. På framsidan stod det Till Elsa, med hennes egen handstil, fast den var rundare och barnsligare än nu.", "Kuvertet var igenklistrat, men det hade aldrig fått något frimärke. Sara satte sig på golvet. Hon visste precis vad som stod i brevet. Hon hade skrivit det för två år sedan, en natt när skulden höll henne vaken."],
      pic: P11[0], say: t3("Sara hittar ett gammalt brev. Vem är det till, och när skrev hon det?", "Sara finds an old letter. Who is it to, and when did she write it?", "تجد سارة رسالة قديمة. لمن هي، ومتى كتبتها؟")},
    {text: ["Allt hade börjat på klassresan i sjuan. Sara och Elsa hade varit bästa vänner sedan förskolan. De hade delat allt: godis, hemligheter och hörlurar på bussen.", "Den sista kvällen hade Elsa berättat en hemlighet. Hon var kär i Viktor i parallellklassen. ”Lova att inte säga något till någon”, hade hon viskat i mörkret. Och Sara hade lovat."],
      pic: P11[1], say: t3("Nu hoppar berättelsen bakåt i tiden. Vilka verbformer visar det?", "Now the story jumps back in time. Which verb forms show that?", "الآن تعود القصّة إلى الوراء في الزمن. ما صيغ الأفعال التي تدلّ على ذلك؟")},
    {text: ["Två veckor senare satt Sara med några tjejer från klassen i matsalen. De pratade om vem som var kär i vem, och alla tittade på henne. Sara ville så gärna höra till.", "”Elsa är kär i Viktor”, sa hon. Orden bara kom ut. Samma eftermiddag visste hela skolan. När Elsa gick förbi i korridoren, sjöng några killar Viktors namn. Elsa sprang in på toaletten och grät."],
      pic: P11[2], say: t3("Sara berättar hemligheten. Varför gör hon det, tror du?", "Sara tells the secret. Why does she do it, do you think?", "تبوح سارة بالسرّ. لماذا تفعل ذلك في رأيك؟")},
    {text: ["Elsa förstod direkt vem som hade berättat. Hon sa aldrig något till Sara. Hon slutade bara prata med henne, och en dag hade hon bytt plats i matsalen.", "Sara kände en skuld som växte för varje vecka. Hon ångrade sig, men ingen ursäkt kunde ersätta det som hade gått sönder. Till slut skrev hon ett brev. Hon bekände allt, men hon skickade det aldrig. Hon var för feg."],
      pic: P11[3], say: t3("Sara känner skuld. Varför skickar hon aldrig brevet?", "Sara feels guilt. Why does she never send the letter?", "تشعر سارة بالذنب. لماذا لم ترسل الرسالة أبدًا؟")},
    {text: ["Nu satt Sara på golvet med brevet i handen. Det hade gått två år. Elsa hade fått nya vänner, och Sara hade Amir. Men någonting fattades fortfarande.", "Hon tänkte på demonstrationen i oktober, när hon inte hade vågat intervjua Elsa. Hon tänkte på dikten hon hade skrivit, där en sekund kunde bli en evighet. Snart skulle de välja olika program och börja på olika gymnasier. Sedan var det för sent."],
      pic: P11[4], say: t3("Nu är vi tillbaka i nuet. Vad bestämmer sig Sara för, tror du?", "Now we are back in the present. What do you think Sara decides?", "عدنا الآن إلى الحاضر. ماذا تظنّ أن سارة ستقرّر؟")},
    {text: ["Nästa morgon väntade Sara vid Elsas skåp. Hon tvekade, osäker på vad hon skulle säga, när hon såg Elsa komma. Hennes händer darrade när hon räckte fram kuvertet. ”Jag skrev det här i sjuan”, sa hon. ”Jag borde ha gett dig det då.”", "Elsa tittade en lång stund på handstilen. Det fanns en risk att hon skulle slänga det. Men hon öppnade kuvertet och läste. Korridoren var full av ljud, men för Sara var det helt tyst."],
      pic: P11[5], say: t3("Sara ger Elsa brevet. Hur visar texten att Sara är nervös?", "Sara gives Elsa the letter. How does the text show that Sara is nervous?", "تعطي سارة إلسا الرسالة. كيف يُظهر النصّ أن سارة متوتّرة؟")},
    {text: ["När Elsa hade läst klart, vek hon ihop brevet. Hennes blick var allvarlig. ”Jag visste att det var du”, sa hon. ”Det värsta var inte att du berättade. Det värsta var att du aldrig sa något.” Sara nickade. Hon fick inte fram ett ord.", "”Men tack”, sa Elsa tyst. ”Det är modigt att säga det nu.” Hon log lite, för första gången på två år. Det var ingen stor försoning med kramar och tårar. Men det var en början, och för första gången på länge kände Sara hopp."],
      pic: P11[6], say: t3("Elsa visste redan. Vad var det värsta för henne?", "Elsa already knew. What was the worst thing for her?", "كانت إلسا تعرف من قبل. ما أسوأ شيء بالنسبة إليها؟")},
    {text: ["På lunchen satte sig Elsa vid Saras och Amirs bord. Ingen sa något om brevet. De pratade om sommarlovet och om vilka program de hade valt.", "Sara kände en lättnad som spred sig i hela kroppen. Senare skrev hon en novell om det som hade hänt till Lenas lektion. Den började med en tillbakablick: Allt hade börjat på klassresan i sjuan."],
      pic: P11[7], say: t3("Hur känner sig Sara nu? Hur börjar hennes novell?", "How does Sara feel now? How does her short story begin?", "بماذا تشعر سارة الآن؟ كيف تبدأ قصّتها القصيرة؟")}],
  wordsSay: t3("Nya ord från novellen! Tryck på ett ord för att se vad det betyder.", "New words from the short story! Tap a word to see what it means.", "كلمات جديدة من القصّة القصيرة! اضغط على كلمة لترى معناها."),
  grammar: [
    {draw: () => {
      const X = [130, 400, 670];
      return [A.wipe(), head(t3("Ännu tidigare: hade + supinum", "Even earlier: hade + supine", "قبلُ ذلك: hade + supinum")), A.arrow(60, 170, 750, 170, "k"),
        ...["sjuan", "maj i nian", "sedan"].map((s, i) => qt(s, X[i], 140, 24, ["o", "b", "k"][i])), ...X.map(x => A.p(`M${x} 160 L${x} 180`, "k", 4)),
        A.tx("hade skrivit", X[0], 240, 34, "o"), A.tx("hittade", X[1], 240, 34, "b"), A.tx("ska ge", X[2], 240, 34, "k"),
        A.tx("Sara hittade brevet.", 400, 330, 34, "b"), A.tx("Hon hade skrivit det för två år sedan.", 400, 390, 34, "o"),
        qt(L(t3("preteritum = berättelsens nu · pluskvamperfekt = ännu tidigare", "past = the story's now · past perfect = even earlier", "الماضي = حاضر القصّة · الماضي التامّ = قبل ذلك")), 400, 450, 22, "k")];
    }, say: t3("Novellen berättas i preteritum: Sara hittade brevet. Men brevet skrevs ännu tidigare, i sjuan. Det visar vi med hade + supinum: Hon hade skrivit det för två år sedan. Det kallas pluskvamperfekt.", "The short story is told in the past: Sara hittade brevet, Sara found the letter. But the letter was written even earlier, in year 7. We show that with hade + supine: Hon hade skrivit det, she had written it. That is called the past perfect.", "تُروى القصّة بالفعل الماضي: Sara hittade brevet، أي وجدت سارة الرسالة. لكنّ الرسالة كُتبت قبل ذلك، في الصفّ السابع. نُظهر ذلك بـ hade مع supinum: Hon hade skrivit det، أي كانت قد كتبتها. ويُسمّى هذا الماضي التامّ.")},
    {draw: () => [A.wipe(), head(t3("hade + supinum", "hade + supine", "hade + supinum")),
      ...boxes([["Hon", "b", "subjekt"], ["hade", "r", "hade"], ["skrivit", "g", "supinum"], ["brevet.", null]], 160, 40),
      ...[["skriva", "skrev", "skrivit"], ["berätta", "berättade", "berättat"], ["lova", "lovade", "lovat"], ["säga", "sa", "sagt"], ["gå", "gick", "gått"]].flatMap(([a, b, c], j) => [A.tx(a, 220, 260 + j * 44, 30, "k"), A.tx(b, 400, 260 + j * 44, 30, "b"), A.tx(`hade ${c}`, 590, 260 + j * 44, 30, "g")])],
    say: t3("Pluskvamperfekt byggs med hade och supinum. Supinum är samma form som efter har: har skrivit, hade skrivit. Lär dig de oregelbundna: skrivit, sagt, gått.", "The past perfect is built with hade and the supine. The supine is the same form as after har: har skrivit, hade skrivit. Learn the irregular ones: skrivit, sagt, gått.", "يُبنى الماضي التامّ من hade وsupinum. وsupinum هي الصيغة نفسها التي تأتي بعد har: har skrivit، hade skrivit. احفظ الأفعال الشاذّة: skrivit، sagt، gått.")},
    {draw: () => [A.wipe(), head(t3("En novell med tillbakablick", "A short story with a flashback", "قصّة قصيرة فيها استرجاع")),
      ...boxes([["NU: Sara hittar brevet", "b"]], 150, 32), A.arrow(400, 175, 400, 215, "k"),
      ...boxes([["TILLBAKABLICK: klassresan i sjuan", "o"]], 250, 32), A.arrow(400, 275, 400, 315, "k"),
      ...boxes([["NU IGEN: Sara ger Elsa brevet", "b"]], 350, 32),
      A.tx("English: She had written it.", 400, 420, 26, "k"), A.tx("بالعربية: كانت قد كتبتها.", 400, 462, 30, "o")],
    say: t3("Novellen börjar i nuet, hoppar bakåt till klassresan i en tillbakablick och kommer sedan tillbaka till nuet. Hade-formerna visar läsaren när vi är på väg in i det förflutna. På engelska säger man had written, och på arabiska كانت قد كتبت.", "The story starts in the present, jumps back to the class trip in a flashback, and then returns to the present. The hade forms show the reader when we are going into the past. In English you say had written, and in Arabic كانت قد كتبت.", "تبدأ القصّة في الحاضر، ثم تعود إلى رحلة الصفّ في استرجاع، ثم ترجع إلى الحاضر. وصيغ hade تُبيّن للقارئ متى ندخل في الماضي. في الإنجليزية نقول had written، وفي العربية: كانت قد كتبت.")}],
  read: [
    {q: "Var hittade Sara brevet?", o: ["Längst in i den nedersta skrivbordslådan", "I sin gamla skolväska", "I Elsas skåp"], why: "Del 1: Längst in i den nedersta lådan låg ett vitt kuvert."},
    {q: "Vilken hemlighet hade Elsa berättat?", o: ["Att hon var kär i Viktor", "Att hon skulle flytta", "Att hon hade fuskat på ett prov"], why: "Del 2: Hon var kär i Viktor i parallellklassen."},
    {q: "Varför skickade Sara aldrig brevet?", o: ["Hon var för feg.", "Hon hade glömt adressen.", "Elsa hade redan flyttat."], why: "Del 4: Hon bekände allt, men hon skickade det aldrig. Hon var för feg."},
    {q: "Vad tyckte Elsa var det värsta?", o: ["Att Sara aldrig sa något efteråt", "Att killarna sjöng i korridoren", "Att Viktor fick veta"], why: "Del 7: ”Det värsta var att du aldrig sa något.”"},
    {q: "Var satte sig Elsa på lunchen?", o: ["Vid Saras och Amirs bord", "Ensam vid fönstret", "Med Viktor"], why: "Del 8: Elsa satte sig vid Saras och Amirs bord."},
    {q: "Varför berättade Sara hemligheten, tror du?", o: ["Hon ville höra till gruppen i matsalen.", "Hon ville hjälpa Elsa och Viktor att bli ihop.", "Viktor hade frågat henne."], why: "Del 3: Alla tittade på henne, och Sara ville så gärna höra till."},
    {q: "Varför gav Sara Elsa brevet just nu, tror du?", o: ["De skulle snart börja på olika gymnasier, och då kunde det vara för sent.", "Lena sa åt henne att göra det.", "Elsa hade frågat efter brevet."], why: "Del 5: Snart skulle de börja på olika gymnasier. Sedan var det för sent."},
    {q: "Vad betyder ”ingen stor försoning … men en början”?", o: ["De var inte bästa vänner igen, men de hade börjat bli sams.", "De blev ovänner igen direkt.", "De kramades och grät länge."], why: "Del 7: Ingen stor försoning med kramar och tårar. Men det var en början."},
    {q: "Hur är novellen uppbyggd?", o: ["Den börjar i nuet, går bakåt i tiden och slutar i nuet igen.", "Den berättar allt i den ordning det hände.", "Den består bara av brev."], why: "Del 1 är nu, del 2–4 är en tillbakablick, del 5–8 är nu igen."}],
  gram(lv, write): Problem {
    const [s, inf, sup, past, pres, rest] = pick(PQ), hint = hintOf(PQH);
    if (write || lv === 2) return {kind: "text", ans: [sup], show: sup, q: [A.wipe(), head(t3("Skriv verbet i supinum.", "Write the verb in the supine.", "اكتب الفعل بصيغة supinum."), 80, 32), ...svLines(`${s} hade ____ ${rest}`, 210, 42), A.tx(`(${inf})`, 400, 370, 40, "o")], sol: svLines(`${s} hade ${sup} ${rest}`, 400, 36, "g"), hint};
    if (lv === 0 || Math.random() < .5) {
      const opts = shuffle([sup, past, pres]);
      return {kind: "choice", opts, ans: opts.indexOf(sup), show: sup, q: [A.wipe(), head(t3("Vilken form passar efter hade?", "Which form fits after hade?", "أي صيغة تناسب بعد hade؟"), 80, 34), ...svLines(`${s} hade ____ ${rest}`, 230, 42), A.tx(`(${inf})`, 400, 360, 36, "o")], sol: svLines(`${s} hade ${sup} ${rest}`, 400, 36, "g"), hint};
    }
    const right = `hade ${sup}`, opts = shuffle([right, `har ${sup}`, pres]), line = `Sara tänkte på att ${low(s)} ____ ${rest}`;
    return {kind: "choice", opts, ans: opts.indexOf(right), show: right, q: [A.wipe(), head(t3("Det hände ännu tidigare. Vilken form passar?", "It happened even earlier. Which form fits?", "حدث ذلك قبلُ. أي صيغة تناسب؟"), 80, 30), ...svLines(line, 230, 40)], sol: svLines(fill(line, right), 400, 34, "g"), hint};
  },
  help: [{say: PQH, draw: () => [A.tx("Sara hittade brevet.", 400, 170, 40, "b"), A.tx("Hon hade skrivit det i sjuan.", 400, 260, 40, "o"), A.tx("hade + skrivit, berättat, sagt", 400, 350, 36, "g")]}]});

